use semio_s_artifact_energy_model_native_mutations::scalar::ScalarStorage as _;
use super::*;
#[path="../../../../📸️snapshot/🧳️state/🧪️tests/🧰️helpers/🦀️.rs"]mod helpers;
use helpers::{corpus,receive,source,grant,observe,drain,central_fragment,project_record,denied_axes};
use semio_framework_value_native_owned::native_decoding::NativeReceive;
fn run<S:ScalarRowPath<Row=StateZone,Branch=ModelGeometryState>>(case:&serde_json::Value,cuts:&[serde_json::Value]) where S::Scalar:NativeReceive<semio_framework_value::DslValue>+std::fmt::Debug{
 assert!(size_of::<ScalarRowPreparation<S>>()<=4096);
 let mut document:serde_json::Value=serde_json::from_str(include_str!("../../../../📸️snapshot/🧬️original/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();document=document["document"].take();document["model"]=corpus()["model"].clone();document["model"]["zones"][0]["id"]=1.into();document["model"]["zones"][0][case["field"].as_str().unwrap()]=case["before"].clone();let original=source(receive::<EnergyModelSnapshot>(&document));let key=source(case["id"].as_u64().unwrap()as u32);let authored=source(receive::<S::Scalar>(&case["value"]));
 for cut in std::iter::once(None).chain(cuts.iter().map(|n|Some(n.as_u64().unwrap()as usize))){let mut owner=ScalarRowPreparation::<S>::new();let mut turns=0;while !owner.ready()&&cut.is_none_or(|cut|turns<cut){let d=owner.demand(authored.borrow(),key.borrow(),original.borrow(),4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.advance(authored.borrow(),key.borrow(),original.borrow(),4096,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.demand(authored.borrow(),key.borrow(),original.borrow(),4096).unwrap(),d);}let(s,h)=observe(||owner.advance(authored.borrow(),key.borrow(),original.borrow(),4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));turns+=1;assert!(turns<10000);}
  if cut.is_none(){assert_eq!(owner.outcome().unwrap().as_str(),case["outcome"].as_str().unwrap());if owner.outcome()==Some(ScalarOutcome::Changed){let g=grant(owner.take_demand().unwrap());let(diff,p)=owner.take(g).unwrap().unwrap();assert!(p.fits(g));let diff=source(diff);let mut post=project_record(original.borrow());assert!(central_fragment(&diff,original.borrow(),&mut post));let after=receive::<S::Scalar>(&case["after"]);assert_eq!(S::read(post.model.geometry.get().zones.get(0).unwrap()),after);assert_eq!(post.model.identity.identity(),original.borrow().get().model.identity.identity());assert_eq!(post.model.materials.identity(),original.borrow().get().model.materials.identity());assert_eq!(post.model.loads.identity(),original.borrow().get().model.loads.identity());assert_eq!(post.model.controls.identity(),original.borrow().get().model.controls.identity());assert_eq!(post.model.systems.identity(),original.borrow().get().model.systems.identity());assert_eq!(post.model.generation.identity(),original.borrow().get().model.generation.identity());assert_eq!(post.model.outputs.identity(),original.borrow().get().model.outputs.identity());let row=post.model.geometry.get().zones.get(0).unwrap();let old=original.borrow().get().model.geometry.get().zones.get(0).unwrap();assert_eq!(row.name.identity(),old.name.identity());let g=grant(owner.inverse_demand().unwrap());let(inverse,p)=owner.take_inverse(g).unwrap().unwrap();assert!(p.fits(g));assert_eq!(inverse,receive::<S::Scalar>(&case["before"]));drain(post);drain(diff);}}
  owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){break;}let d=owner.close_demand(4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.close_step(denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.close_demand(4096).unwrap(),d);}let(s,h)=observe(||owner.close_step(g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));assert_eq!(S::read(original.borrow().get().model.geometry.get().zones.get(0).unwrap()),receive::<S::Scalar>(&case["before"]));
 }drain(authored);drain(key);drain(original);
}
#[test]
fn native_zone_scalar_preparation_rebuilds_only_changed_original_paths_and_cancels_each_prefix(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let cuts=law["cancelAt"].as_array().unwrap();for case in law["cases"].as_array().unwrap(){match case["field"].as_str().unwrap(){"volume_m3"=>run::<Volume>(case,cuts),"multiplier"=>run::<Multiplier>(case,cuts),"conditioned"=>run::<Conditioned>(case,cuts),"part_of_total_floor_area"=>run::<FloorArea>(case,cuts),_=>panic!("authored native Zone scalar field")}}
}

#[derive(Debug,semio_framework_value::ToValue,semio_framework_value::FromValue,semio_framework_value::RetireOwned)]
struct VolumeOperation{id:u32,value:f64}
impl protocol::Mutation<EnergyModelSnapshot> for VolumeOperation{type Diff=EnergyModelDiff;const DESCRIPTORS:&'static[protocol::MutationLeafDescriptor]=&[];fn descriptor(&self)->&'static protocol::MutationLeafDescriptor{panic!("fixture exercises only retained semantic ports")}}
impl semio_s_artifact_energy_model_native_mutations::scalar::ScalarLeafSpec<VolumeOperation,VolumeOperation> for Volume{
 const INVALID:protocol::mutation::retained::RetainedDiagnosticSpec=protocol::mutation::retained::RetainedDiagnosticSpec{level:store::__diagnostic::Severity::Fatal,code:"mutation.invariant",message:"A zone volume must be positive and finite."};
 const MISSING:protocol::mutation::retained::RetainedDiagnosticSpec=protocol::mutation::retained::RetainedDiagnosticSpec{level:store::__diagnostic::Severity::Error,code:"mutation.target-missing",message:"The addressed zone does not exist."};
 const UNCHANGED:protocol::mutation::retained::RetainedDiagnosticSpec=protocol::mutation::retained::RetainedDiagnosticSpec{level:store::__diagnostic::Severity::Warning,code:"mutation.no-op",message:"The zone already has this volume."};
 fn input(payload:RetainedCloneRef<'_,VolumeOperation>)->RetainedCloneRef<'_,f64>{payload.project(0,|p|&p.value)}
 fn key(payload:RetainedCloneRef<'_,VolumeOperation>)->RetainedCloneRef<'_,u32>{payload.project(1,|p|&p.id)}
 fn inverse(payload:RetainedCloneRef<'_,VolumeOperation>,value:f64)->VolumeOperation{VolumeOperation{id:payload.get().id,value}}
}
#[test]
fn shared_native_scalar_leaf_preserves_typed_decisions_numeric_targets_and_exact_inverse_custody(){
 use semio_s_artifact_energy_model_native_mutations::scalar::ScalarLeafPreparation;
 use protocol::mutation::retained::{RetainedMutationLeafPreparation,RetainedMutationAdvance,RetainedMutationDecision,RetainedMutationCloseContext};
 type Owner=ScalarLeafPreparation<VolumeOperation,VolumeOperation,Volume>;
 assert!(size_of::<Owner>()<=4096);
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 for case in law["cases"].as_array().unwrap().iter().filter(|row|row["field"]=="volume_m3"){
  let mut document:serde_json::Value=serde_json::from_str(include_str!("../../../../📸️snapshot/🧬️original/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();document=document["document"].take();document["model"]=corpus()["model"].clone();document["model"]["zones"][0]["id"]=1.into();document["model"]["zones"][0]["volume_m3"]=case["before"].clone();let original=source(receive::<EnergyModelSnapshot>(&document));let payload=source(VolumeOperation{id:case["id"].as_u64().unwrap()as u32,value:case["value"].as_f64().unwrap()});
  for cutoff in std::iter::once(None).chain((0..200).map(Some)){
   let mut owner=Owner::new();let mut ready=false;for _ in 0..cutoff.unwrap_or(10000){let d=owner.decision_demand(payload.borrow(),original.borrow(),4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.decide(payload.borrow(),original.borrow(),4096,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.decision_demand(payload.borrow(),original.borrow(),4096).unwrap(),d);}let(s,h)=observe(||owner.decide(payload.borrow(),original.borrow(),4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));if matches!(s,RetainedMutationAdvance::Ready(_)){ready=true;break;}}
   let mut diff=None;let mut inverse=None;if ready{match owner.take_decision(){RetainedMutationDecision::Refused(messages)=>{assert!(case["outcome"]=="invalid"||case["outcome"]=="missing");assert_eq!(messages[0].target,[case["id"].as_u64().unwrap().to_string()]);close_messages(messages);},RetainedMutationDecision::Admitted(value,messages)=>{assert!(case["outcome"]=="changed"||case["outcome"]=="no-op");assert_eq!(messages.len(),usize::from(case["outcome"]=="no-op"));close_messages(messages);let value=source(value);for _ in 0..cutoff.unwrap_or(10000){let g=grant(owner.inverse_demand(payload.borrow(),original.borrow(),value.borrow(),4096).unwrap());let(s,h)=observe(||owner.inverse(payload.borrow(),original.borrow(),value.borrow(),4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));if matches!(s,RetainedMutationAdvance::Ready(_)){if cutoff.is_none(){let rows=owner.take_inverse();assert_eq!(rows.len(),usize::from(case["outcome"]=="changed"));if let Some(row)=rows.first(){assert_eq!(row.id,payload.borrow().get().id);assert_eq!(row.value,case["before"].as_f64().unwrap());}inverse=Some(rows);}break;}}diff=Some(value);}}}else{assert!(cutoff.is_some());}
   let factory=semio_framework_value::factory::OwnedValueRetirementFactory::<VolumeOperation>::default();let context=RetainedMutationCloseContext{mutations:&factory};owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){break;}let d=owner.close_demand(context,4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.close_step(context,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.close_demand(context,4096).unwrap(),d);}let(s,h)=observe(||owner.close_step(context,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));if let Some(diff)=diff{drain(diff);}if let Some(inverse)=inverse{drain(inverse);}
  }drain(payload);drain(original);
 }
}
fn close_messages(messages:Vec<protocol::MutationMessage>){let mut owner=protocol::MutationMessageLedgerRetirement::new(String::new(),messages);for _ in 0..10000{if owner.terminal_is_empty(){return;}let d=semio_framework_value::RetirementDemand{copy_bytes:owner.next_copy_byte_demand(),capacity_bytes:owner.next_capacity_byte_demand(4096).unwrap(),release_bytes:owner.next_release_byte_demand().unwrap(),depth:owner.next_depth_demand().unwrap()};let g=grant(d);let(s,h)=observe(||owner.close_step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}panic!("native scalar diagnostic close stalled");}
